const __inputRaw = workflowContext.actions['Wait_For_Result_From_Ai'].outputs.body;
const __inputValues = Array.isArray(__inputRaw) ? __inputRaw : [__inputRaw];
const items = __inputValues.map(value =>
  value && typeof value === 'object' && 'json' in value ? value : { json: value }
);
const __unwrap = value => {
  if (Array.isArray(value)) {
    return value.map(item =>
      item && typeof item === 'object' && 'json' in item ? item.json : item
    );
  }
  return value && typeof value === 'object' && 'json' in value ? value.json : value;
};
const __node = name => {
  const output = workflowContext.actions[name]?.outputs;
  const raw = output && typeof output === 'object' && 'body' in output
    ? output.body
    : output;
  const values = Array.isArray(raw) ? raw : [raw];
  const wrapped = values.map(value =>
    value && typeof value === 'object' && 'json' in value ? value : { json: value }
  );
  return {
    item: wrapped[0],
    first: () => wrapped[0],
    last: () => wrapped[wrapped.length - 1],
    all: () => wrapped
  };
};

const __results = items.map(item => {
  const $json = item.json;
  const $input = {
    item,
    first: () => item,
    last: () => item,
    all: () => items
  };
  return (() => {
const item = $input.item.json;
let parsed = {};

try {
  const raw = item.output || item.response || item.text || '{}';
  const cleaned = raw.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  // Fallback defaults if AI response parse fails
  parsed = {
    virality_score: 50,
    score_tier: 'MODERATE',
    component_scores: { trend_alignment: 50, engagement_prediction: 50, timing_score: 50, historical_similarity: 50, media_bonus: 50 },
    key_drivers: ['Unable to parse AI response — using defaults'],
    pattern_matches: [],
    weaknesses: ['AI response parse error'],
    recommendations: ['Re-run analysis or check AI node output'],
    best_publish_time: new Date().toISOString(),
    predicted_engagement_range: { low: 0.01, high: 0.03 },
    confidence: 'LOW'
  };
}

const score = parsed.virality_score ?? 50;
const tier = score >= 75 ? 'HIGH' : score >= 40 ? 'MODERATE' : 'LOW';

return {
  json: {
    ...item,
    ...parsed,
    virality_score: score,
    score_tier: tier,
    analysis_timestamp: new Date().toISOString(),
    scored_submission_id: item.submission_id
  }
};
  })();
});
return { body: __unwrap(__results) };

